@layer hj.components {
  /* Customise: --hj-citation-width (card width) */
  .hj-citation-trigger {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 18px;
    height: 18px;
    margin: 0 2px;
    padding: 0 calc(5px * var(--hj-density));
    border-radius: var(--hj-radius-pill);
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg-dim);
    font: 500 11px / 1 var(--hj-font-mono);
    font-variant-numeric: tabular-nums;
    text-decoration: none;
    vertical-align: 0.14em;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-citation-trigger::before {
    content: '';
    position: absolute;
    inset: -8px -4px;
  }
  .hj-citation-trigger:hover,
  .hj-citation-trigger[data-popup-open] {
    background: var(--hj-accent-soft);
    box-shadow: inset 0 0 0 1px transparent;
    color: var(--hj-accent);
  }

  .hj-citation-positioner {
    z-index: var(--hj-z-popover);
  }
  .hj-citation-popup {
    width: var(--hj-citation-width, 300px);
    max-width: var(--available-width);
    padding: calc(14px * var(--hj-density)) calc(16px * var(--hj-density));
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-radius-md);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    box-shadow: var(--hj-shadow-lift);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    transform-origin: var(--transform-origin);
    transition:
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  /* Grows from the chip. */
  .hj-citation-popup[data-starting-style],
  .hj-citation-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.96);
  }
  .hj-citation-popup[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
  .hj-citation-domain {
    display: flex;
    align-items: center;
    gap: calc(7px * var(--hj-density));
    margin-bottom: calc(6px * var(--hj-density));
    font-size: 12px;
    color: var(--hj-fg-mute);
  }
  .hj-citation-favicon {
    display: grid;
    place-items: center;
    width: 16px;
    height: 16px;
    border-radius: 4px;
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg-dim);
    font-size: 9.5px;
    font-weight: 700;
  }
  .hj-citation-title {
    font-size: 14px;
    font-weight: 600;
    line-height: 1.35;
    letter-spacing: -0.01em;
  }
  .hj-citation-snippet {
    margin: calc(6px * var(--hj-density)) 0 0;
    font-size: 12.5px;
    line-height: 1.5;
    color: var(--hj-fg-dim);
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .hj-citation-list {
    display: grid;
    gap: 2px;
    margin: 0;
    padding: 0;
    list-style: none;
    font-family: var(--hj-font-sans);
  }
  .hj-citation-list-item {
    margin: 0;
  }
  .hj-citation-list-link,
  .hj-citation-list-item:not(:has(a)) {
    display: grid;
    grid-template-columns: 22px minmax(0, 1fr) auto;
    align-items: baseline;
    gap: calc(8px * var(--hj-density));
    padding: calc(6px * var(--hj-density)) calc(8px * var(--hj-density));
    border-radius: var(--hj-radius-xs);
    corner-shape: var(--hj-corner-shape, round);
    color: var(--hj-fg);
    text-decoration: none;
    font-size: 13px;
    transition: background-color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-citation-list-link:hover {
    background: color-mix(in srgb, var(--hj-fg) 5%, transparent);
  }
  .hj-citation-list-index {
    font: 500 11px / 1 var(--hj-font-mono);
    color: var(--hj-fg-mute);
    font-variant-numeric: tabular-nums;
  }
  .hj-citation-list-title {
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  .hj-citation-list-domain {
    font-size: 12px;
    color: var(--hj-fg-mute);
  }
}

'use client';
import { PreviewCard as Base } from '@base-ui/react/preview-card';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

export const Root: typeof Base.Root = Base.Root;
export const Positioner: HanjiPart<typeof Base.Positioner> = part(
  Base.Positioner,
  'Citation.Positioner',
  'hj-citation-positioner',
);
export const Popup: HanjiPart<typeof Base.Popup> = part(
  Base.Popup,
  'Citation.Popup',
  'hj-citation-popup',
);

/** Portals to `<body>` and keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

export interface TriggerOwnProps {
  /** The source's number, shown as the chip and used for the accessible label. */
  index: number;
}
export interface TriggerProps extends TriggerOwnProps, Base.Trigger.Props {}

/**
 * The inline `[1]` chip. Renders a link to the source (`href`); hovering or focusing it opens the
 * preview after a short delay.
 */
export function Trigger(props: TriggerProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    index,
    className,
    children,
    delay = 350,
    ...rest
  } = withDefaults(config, 'Citation.Trigger', props);
  return (
    <Base.Trigger
      aria-label={`Source ${index}`}
      target="_blank"
      rel="noreferrer"
      {...rest}
      delay={delay}
      className={cls(config, 'Citation.Trigger', 'hj-citation-trigger', className)}
    >
      {children ?? index}
    </Base.Trigger>
  );
}

export interface ContentOwnProps {
  /** Gap between the chip and the card. @default 8 */
  sideOffset?: number;
  /** @default 'top' */
  side?: 'top' | 'bottom' | 'left' | 'right';
}
export interface ContentProps extends ContentOwnProps, Base.Popup.Props {}

/** Shorthand: Portal + Positioner + Popup — the source card. */
export function Content({
  sideOffset = 8,
  side = 'top',
  ...popup
}: ContentProps): React.ReactElement {
  return (
    <Portal>
      <Positioner sideOffset={sideOffset} side={side}>
        <Popup {...popup} />
      </Positioner>
    </Portal>
  );
}

/** The source's site, e.g. `example.com`, with its initial as a glyph. */
export function Domain(props: ElementPartProps<'div'>): React.ReactElement {
  const config = useHanjiConfig();
  const { className, children, render, ...rest } = withDefaults(config, 'Citation.Domain', props);
  const initial =
    typeof children === 'string'
      ? children
          .replace(/^www\./, '')
          .charAt(0)
          .toUpperCase()
      : '·';
  return useRender({
    render,
    defaultTagName: 'div',
    props: {
      ...rest,
      className: cls(config, 'Citation.Domain', 'hj-citation-domain', className) as
        | string
        | undefined,
      children: (
        <>
          <span className={config.unstyled ? undefined : 'hj-citation-favicon'} aria-hidden="true">
            {initial}
          </span>
          {children}
        </>
      ),
    },
  });
}

export const Title: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Citation.Title',
  'hj-citation-title',
);
export const Snippet: (props: ElementPartProps<'p'>) => React.ReactElement = elementPart(
  'p',
  'Citation.Snippet',
  'hj-citation-snippet',
);

/** The numbered list of sources under a reply. */
export const List: (props: ElementPartProps<'ol'>) => React.ReactElement = elementPart(
  'ol',
  'Citation.List',
  'hj-citation-list',
);

export interface ListItemOwnProps {
  index: number;
  /** Link to the source. */
  href?: string;
  /** Shown after the title, muted. */
  domain?: string;
}
export interface ListItemProps extends ListItemOwnProps, React.ComponentProps<'li'> {}

/** One source in Citation.List: number, title, domain. */
export function ListItem(props: ListItemProps): React.ReactElement {
  const config = useHanjiConfig();
  const { index, href, domain, className, children, ...rest } = withDefaults(
    config,
    'Citation.ListItem',
    props,
  );
  const styled = !config.unstyled;
  const body = (
    <>
      <span className={styled ? 'hj-citation-list-index' : undefined}>{index}</span>
      <span className={styled ? 'hj-citation-list-title' : undefined}>{children}</span>
      {domain ? (
        <span className={styled ? 'hj-citation-list-domain' : undefined}>{domain}</span>
      ) : null}
    </>
  );
  return (
    <li
      {...rest}
      className={
        cls(config, 'Citation.ListItem', 'hj-citation-list-item', className) as string | undefined
      }
    >
      {href ? (
        <a
          href={href}
          target="_blank"
          rel="noreferrer"
          className={styled ? 'hj-citation-list-link' : undefined}
        >
          {body}
        </a>
      ) : (
        body
      )}
    </li>
  );
}

export * as Citation from './citation.tsx';
export type {
  ContentProps as CitationContentProps,
  ListItemProps as CitationListItemProps,
  TriggerProps as CitationTriggerProps,
} from './citation.tsx';
